import{_ as i,C as t,o as l,c as r,E as o,a2 as n}from"./chunks/framework.BOeh4kYD.js";const _=JSON.parse('{"title":"选对技能，不等于获得执行权","description":"","frontmatter":{"title":"选对技能，不等于获得执行权","date":"2026-09-16","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"智能体运行时按需选择技能而非永久预载时，一次正确路由究竟能证明什么；在执行或宣告成功前，哪些下游事实必须继续分开？","summary":"技能路由可以成为可测量的运行时选择平面，减少永久预载的上下文负担；但正确路由只证明选择相关性，不能生成工具权限，也不能证明后续执行和业务结果成功。","sources":["research/analysis/Q-20260916-03-skill-routing-is-selection-not-authority.md"],"item_id":"Q-20260916-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-16-right-skill-not-execution-authority-cover-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-16-right-skill-not-execution-authority.md","filePath":"zh/engineering/2026-09-16-right-skill-not-execution-authority.md","lastUpdated":1789665186000}'),s={name:"zh/engineering/2026-09-16-right-skill-not-execution-authority.md"};function h(p,e,c,u,d,g){const a=t("ArticleCover");return l(),r("div",null,[o(a,{image:"/assets/covers/daily-2026-09-16-right-skill-not-execution-authority-cover-v2.webp",kicker:"开源工程 · 每日研究",title:"选对技能，不等于获得执行权",summary:"技能路由可以成为可测量的运行时选择平面，减少永久预载的上下文负担；但正确路由只证明选择相关性，不能生成工具权限，也不能证明后续执行和业务结果成功。",version:"Q-20260916-03",status:"Daily Runtime V5 · 2026-09-16",languageHref:"/en/engineering/2026-09-16-right-skill-not-execution-authority",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="选对技能-不等于获得执行权" tabindex="-1">选对技能，不等于获得执行权 <a class="header-anchor" href="#选对技能-不等于获得执行权" aria-label="Permalink to &quot;选对技能，不等于获得执行权&quot;">​</a></h1><p>一个路由器判断当前任务需要“邮件处理”技能，并把对应说明加载进上下文。选择可能完全正确，但数字员工是否能向这个收件人发送邮件，是否需要审批，以及邮件最终是否送达，仍是三个尚未回答的问题。</p><p>技能相关性、执行权限和业务结果属于不同证据身份。把它们压成“技能已选中”，会让一项上下文优化悄悄升级成权力来源，也让后续失败无法定位。</p><h2 id="路由已经是一个可测量组件" tabindex="-1">路由已经是一个可测量组件 <a class="header-anchor" href="#路由已经是一个可测量组件" aria-label="Permalink to &quot;路由已经是一个可测量组件&quot;">​</a></h2><p>同日研究对象分析了一套按需技能路由方法及其技能轨迹集。报告在一个三百二十亿参数的模型设置下，路由器在被评估技能使用任务上的正确技能触发率达到 90.9%。配套数据集包含四种场景中的 372 条轨迹，用于检验路由与技能使用，而不只是一个静态问题集。</p><p>这些结果支持一个工程判断：技能路由可以被独立训练、评估和比较，不必继续藏在提示词拼接里。它的输入、版本、选择结果与测试标签都可以成为运行时事实。</p><p>但 90.9% 仍然是特定设置里的路由质量，不是生产可靠性。它不证明选中的技能说明正确，也不证明当前角色有权执行技能中提到的操作。</p><h2 id="按需加载的价值是缩小上下文" tabindex="-1">按需加载的价值是缩小上下文 <a class="header-anchor" href="#按需加载的价值是缩小上下文" aria-label="Permalink to &quot;按需加载的价值是缩小上下文&quot;">​</a></h2><p>该系统使用轻量的隐藏状态观察、技能库与显式路由或裁决层，决定哪些技能材料被载入，而不是永久把整个技能目录塞进上下文。</p><p>这种设计的直接价值是减少无关令牌和技能之间的竞争。目录较大、任务动态变化时，按需加载还能让系统明确记录“为什么这次看到了这些说明”。</p><p>相反，小型静态目录可能无需额外路由器，显式绑定技能更简单。是否采用路由取决于目录规模、上下文成本和动态资格，而不是为了追求架构复杂度。</p><h2 id="正确路由只证明选择相关性" tabindex="-1">正确路由只证明选择相关性 <a class="header-anchor" href="#正确路由只证明选择相关性" aria-label="Permalink to &quot;正确路由只证明选择相关性&quot;">​</a></h2><p>路由基准通常回答：给定任务标签，系统是否选择了预期技能。它不回答：</p><ul><li>该技能内容是否经过验证并适用于当前版本；</li><li>当前角色是否可以调用技能关联工具；</li><li>精确操作与目标是否符合策略；</li><li>外部调用是否成功且没有未知副作用；</li><li>最终业务结果是否被责任主体接受。</li></ul><p>因此，不能由“路由正确”推断“执行获准”，也不能由最终成功倒推路由一定正确。一个 执行工作器可能误路由后偶然完成任务，也可能正确路由后因权限不足而被阻止。两种情况都需要保留真实原因。</p><h2 id="路由事件应绑定精确版本" tabindex="-1">路由事件应绑定精确版本 <a class="header-anchor" href="#路由事件应绑定精确版本" aria-label="Permalink to &quot;路由事件应绑定精确版本&quot;">​</a></h2><p>只记录“选中了邮件技能”还不够。人类可读名称可能对应多个版本，目录也可能在路由与执行之间发生变化。</p><p>一条可归因的路由记录应包含：</p><ul><li>请求或任务身份、有限上下文摘要与执行轮次；</li><li>当时生效的角色和策略版本；</li><li>技能目录摘要以及经过资格过滤的候选集合；</li><li>路由器或模型版本、排名、置信或裁决依据；</li><li>选中的技能标识符与精确内容哈希，或显式无技能结果；</li><li>真正装入上下文的版本、顺序、截断与转换。</li></ul><p>如果目录或相关上下文发生实质变化，旧路由决定应失效或重新评估，而不是继续引用一个已经改变的技能名称。</p><h2 id="权限必须绑定后来提出的操作" tabindex="-1">权限必须绑定后来提出的操作 <a class="header-anchor" href="#权限必须绑定后来提出的操作" aria-label="Permalink to &quot;权限必须绑定后来提出的操作&quot;">​</a></h2><p>技能说明可以告诉 执行工作器如何调用工具，却不能授予权力。真正的授权判断应发生在调用时，并绑定精确操作、工具、目标、参数、当前策略以及必要审批。</p><p>这意味着资格过滤与语义路由也应分开。系统可以先用确定性规则排除当前角色绝对不能使用的技能，再让路由器在合格集合中判断相关性。即便技能合格，具体调用仍需根据目标和副作用重新检查。</p><p>多技能组合尤其需要谨慎。两个技能分别合格，不代表它们组合出的跨系统操作自动获准。组合本身应成为可观察决定，并在调用边界接受权限判断。</p><h2 id="结果证据属于下游" tabindex="-1">结果证据属于下游 <a class="header-anchor" href="#结果证据属于下游" aria-label="Permalink to &quot;结果证据属于下游&quot;">​</a></h2><p>路由完成后，至少还有三类事实：提出了什么操作，是否获准执行，外部发生了什么。结果记录应包含工具返回、外部效果、失败或阻断原因，以及最终验收状态。</p><p>这样，系统可以分别表达“路由错误”“技能过期”“操作无权”“工具失败”“效果未知”和“业务未完成”。恢复时也能判断应重新路由、重新授权、重试工具还是核对外部效果。</p><p>若只保存最终成功，路由器无法获得可信反馈；若只保存路由命中，运行时又会高估整个任务。选择面与结果面需要互相引用，但不能互相替代。</p><h2 id="一条受治理的技能路径" tabindex="-1">一条受治理的技能路径 <a class="header-anchor" href="#一条受治理的技能路径" aria-label="Permalink to &quot;一条受治理的技能路径&quot;">​</a></h2><p>最小路径可以分成五步：</p><ol><li>根据角色、策略和环境做确定性资格过滤；</li><li>在合格目录上执行语义路由，并允许显式无技能或歧义结果；</li><li>绑定并加载精确技能版本，记录顺序和变换；</li><li>执行工作器提出具体操作后，在调用时独立授权；</li><li>保存执行、外部效果和业务验收证据。</li></ol><p>每一步都可能失败，也应拥有自己的恢复策略。目录变化需要重新路由；权限变化需要重新授权；效果未知需要先核对外部状态，而不是简单重放。</p><h2 id="边界与开放问题" tabindex="-1">边界与开放问题 <a class="header-anchor" href="#边界与开放问题" aria-label="Permalink to &quot;边界与开放问题&quot;">​</a></h2><p>现有证据来自有限且经过整理的评估，包含 372 条轨迹和特定模型、场景。它没有建立恶意技能描述、角色隔离、目录高频变化或超长企业会话下的稳健性，也没有定义生产授权协议。</p><p>仍待研究的问题包括：资格过滤应在路由前还是路由后进行；置信度怎样触发人工或经理审批；技能在执行前更新时旧决定如何失效；多技能权限怎样组合；恢复后能否重用原路线；路由基准怎样关联下游结果而不把两种身份合并。</p><p>有界结论是：<strong>技能路由决定的是哪些材料进入上下文，不是哪些副作用获得许可。选对技能是选择质量证据，执行权与完成证据必须在下游分别建立。</strong></p><p><strong>证据与来源：</strong></p><ul><li><a href="https://arxiv.org/abs/2609.15982" target="_blank" rel="noreferrer">按需技能路由方法与技能轨迹集研究</a>，2026。</li></ul>',38))])}const b=i(s,[["render",h]]);export{_ as __pageData,b as default};
